@dataclass
class MessageHeader:
    """ ----------------------------------------------------------------------
     The root Message type
     This union enables us to easily send different message types without
     redundant storage, and in the future we can easily add new message types.

     Arrow implementations do not need to implement all of the message types,
     which may include experimental metadata types. For maximum compatibility,
     it is best to send data using RecordBatch
    """

    value: Union[
        "Schema",
        "DictionaryBatch",
        "RecordBatch",
        "Tensor",
        "SparseTensor",
    ]

    def serialize_to(self, builder: Builder) -> Tuple[int, int]:
        from .generated.MessageHeader import MessageHeader
        offset = self.value.serialize_to(builder)
        if isinstance(self.value, Schema):
            return (offset, MessageHeader().Schema)
        elif isinstance(self.value, DictionaryBatch):
            return (offset, MessageHeader().DictionaryBatch)
        elif isinstance(self.value, RecordBatch):
            return (offset, MessageHeader().RecordBatch)
        elif isinstance(self.value, Tensor):
            return (offset, MessageHeader().Tensor)
        elif isinstance(self.value, SparseTensor):
            return (offset, MessageHeader().SparseTensor)
        raise ValueError("Invalid union type")

    @classmethod
    def from_fbs(cls, o: Optional[Table], ty: int) -> Self:
        assert o is not None
        source = o.Bytes
        pos = o.Pos
        MessageHeader_ty_instance = FbsMessageHeader()
        if ty == MessageHeader_ty_instance.Schema:
            val = FbsSchema();
            val.Init(source, pos)
            return cls(Schema.from_fbs(val))
        elif ty == MessageHeader_ty_instance.DictionaryBatch:
            val = FbsDictionaryBatch();
            val.Init(source, pos)
            return cls(DictionaryBatch.from_fbs(val))
        elif ty == MessageHeader_ty_instance.RecordBatch:
            val = FbsRecordBatch();
            val.Init(source, pos)
            return cls(RecordBatch.from_fbs(val))
        elif ty == MessageHeader_ty_instance.Tensor:
            val = FbsTensor();
            val.Init(source, pos)
            return cls(Tensor.from_fbs(val))
        elif ty == MessageHeader_ty_instance.SparseTensor:
            val = FbsSparseTensor();
            val.Init(source, pos)
            return cls(SparseTensor.from_fbs(val))
        else:
            raise ValueError("Invalid union type")

    @classmethod
    def make_default(cls) -> Self:
        return cls(Schema.make_default())

    def __eq__(self, other) -> bool:
        if type(self.value) is not type(other.value):
            return False
        return self.value == other.value

@dataclass
class FieldNode:
    """ ----------------------------------------------------------------------
     Data structures for describing a table row batch (a collection of
     equal-length Arrow arrays)
     Metadata about a field at some level of a nested type tree (but not
     its children).

     For example, a List<Int16> with values `[[1, 2, 3], null, [4], [5, 6], null]`
     would have {length: 5, null_count: 2} for its List node, and {length: 6,
     null_count: 0} for its Int16 node, as separate FieldNode structs
    """

    # The number of value slots in the Arrow array at this level of a nested
    # tree
    length: "int"

    # The number of observed nulls. Fields with null_count == 0 may choose not
    # to write their physical validity bitmap out as a materialized buffer,
    # instead setting the length of the bitmap buffer to 0.
    null_count: "int"

    @classmethod
    def from_fbs(cls, o: FbsFieldNode) -> Self:
        length = o.Length()
        null_count = o.NullCount()
        return cls(length, null_count)

    def serialize_to(self, builder: Builder) -> int:
        from .generated.FieldNode import CreateFieldNode
        length = self.length
        null_count = self.null_count
        return CreateFieldNode(builder, length, null_count)

    @classmethod
    def make_default(cls) -> Self:
        length = 0
        null_count = 0
        return cls(length, null_count)

    def __eq__(self, other) -> bool:
        eq = True
        eq = eq and self.length == other.length
        eq = eq and self.null_count == other.null_count

        return eq

